// AUTO-GENERATED by scripts/tts-edge.py — do not hand-edit.
// source: "estimated" = word times spread across each line's window by length.
// Run `python3 scripts/tts-edge.py` on a machine with internet access to
// regenerate this file with exact edge-tts word boundaries + public/beerflood/voice.mp3.
import { LINES } from "./script";

export type Word = { text: string; start: number; end: number; line: string };

const estimate = (): Word[] => {
  const out: Word[] = [];
  for (const line of LINES) {
    const words = line.text.split(" ");
    const weights = words.map((w) => w.replace(/[^\p{L}\p{N}]/gu, "").length + 1.2);
    const total = weights.reduce((a, b) => a + b, 0);
    let t = line.start;
    words.forEach((w, i) => {
      const dur = ((line.end - line.start) * weights[i]) / total;
      out.push({ text: w, start: t, end: t + dur, line: line.id });
      t += dur;
    });
  }
  return out;
};

export const VO_SOURCE: "estimated" | "edge-tts" = "estimated";
export const WORDS: Word[] = estimate();
